}

/* prereqs */
function prMarkdown(a){
  if(typeof a.markdown==="string"&&a.markdown)return a.markdown;
  var L=["## Prerequisites","","Set these up before you follow the steps.",""];
  (a.system_packages||[]).forEach(function(x){L.push("- `"+x+"`")});
  if(a.python)L.push("- Python "+a.python);
  (a.path||[]).forEach(function(x){L.push("- `"+x+"` on your PATH")});
  (a.secrets||[]).forEach(function(x){L.push("- `"+x+"` (a secret you supply)")});
  return L.join("\n")+"\n";
}
function renderPrereqs(d){
  var a=d.prereqs,A=$("asm");A.textContent="";
  if(!a||typeof a!=="object")return false;
  var ev=Array.isArray(a.evidence)?a.evidence:[],byItem={};
  ev.forEach(function(e){if(e&&e.item!=null&&!byItem[e.item])byItem[e.item]=e});
  var items=[],seen={};
  function add(name,kind,key){key=key||name;seen[key]=1;items.push({name:name,kind:kind,e:byItem[key]})}
  (Array.isArray(a.system_packages)?a.system_packages:[]).forEach(function(x){add(String(x),"system package")});
  if(a.python)add("Python "+a.python,"Python version","python");
  (Array.isArray(a.path)?a.path:[]).forEach(function(x){add(String(x),"on your PATH","PATH:"+x)});
  (Array.isArray(a.secrets)?a.secrets:[]).forEach(function(x){add(String(x),"secret")});
  ev.forEach(function(e){if(e&&e.item!=null&&!seen[e.item]&&!/^PATH:/.test(e.item)&&(a.tools||[]).indexOf(e.item)>=0)add(String(e.item),"tool")});
  var ul=el("ul");
  items.forEach(function(it){
    var li=el("li"),h=el("b",null,it.name);h.appendChild(el("span","k",it.kind));li.appendChild(h);
    var why="";
    if(it.e)why=(it.e.step_id!=null?"Step "+it.e.step_id+": ":"")+(it.e.error_line||"");
    li.appendChild(el("span","r",why||"Needed by the docs commands."));
    ul.appendChild(li);
  });
  if(items.length)A.appendChild(ul);else A.appendChild(el("p","none","The docs assume nothing beyond the base image."));
  var ok=!!a.proven,pf=el("div","pf "+(ok?"ok":"bad"));
  var sp=a.steps_passed!=null&&a.steps_total!=null?a.steps_passed+"/"+a.steps_total+" steps":"";
  pf.appendChild(document.createTextNode(ok?"Proven"+(sp?": a fresh container with only these prerequisites ran "+sp+" as written.":": a fresh container with only these prerequisites ran the steps as written."):"Not proven"+(sp?": the fresh container passed "+sp+".":".")));
  var bits=[];if(a.image)bits.push("Image "+a.image);if(a.rounds)bits.push(a.rounds+" round"+(a.rounds===1?"":"s"));
  if(typeof a.note==="string"&&a.note)bits.push(a.note.replace(/\.$/,""));
  if(bits.length)pf.appendChild(el("small",null,bits.join(". ")+"."));
  A.appendChild(pf);
  var w=el("div","pfa"),cb=el("button","ghost","Copy the Prerequisites block");cb.type="button";
  var md=prMarkdown(a);cb.addEventListener("click",function(){copy(this,md)});
  w.appendChild(cb);A.appendChild(w);
  return true;
}
